final class ChainHandler: LogHandler {
    var metadata: Logger.Metadata = [:]; var logLevel: Logger.Level = .info
    private let lock = NSLock(); private var prev = Data(); private var seq: UInt64 = 0
    func log(level: Logger.Level, message: Logger.Message, metadata: Logger.Metadata?, source: String,
             file: String, function: String, line: UInt) {
        lock.lock(); defer { lock.unlock() }                // LogHandler runs on any queue
        let body = canonical(level, message, metadata ?? [:], source)  // redact, stable order
        var mac = HMAC<SHA256>.init(key: key)
        mac.update(data: prev)
        mac.update(data: withUnsafeBytes(of: seq.bigEndian) { Data($0) }); mac.update(data: body)
        prev = Data(mac.finalize()); seq += 1; sink.append(prev, body)   // O_APPEND + fsync
    }
}
